    public function CheckDatabase():string{try{$this->InitializeStorage();$m='CSV Storage OK. API-Keys: '.count($this->ReadCsvAssoc('api_keys')).', Scans: '.count($this->ReadCsvAssoc('scans')).', Observations: '.count($this->ReadCsvAssoc('observations')).', Devices: '.count($this->ReadCsvAssoc('devices')).', Schema: v'.self::SCHEMA_VERSION;$this->SetValueSafe('StorageStatus',$m);return $m;}catch(Throwable $e){return 'CSV-Fehler: '.$e->getMessage();}}
    public function TestConnection():string{try{$r=$this->ApiGet(['34.4001.value']);return isset($r['data']['34.4001.value'])?'Verbindung OK. pH-Key empfangen.':'Verbindung OK, aber pH-Key nicht enthalten.';}catch(Throwable $e){return 'Verbindungsfehler: '.$e->getMessage();}}
    public function TestApiKeyFor(string $key):string{$key=trim($key);if($key==='')return'Keine Browser-Zeile ausgewaehlt.';try{$r=$this->ApiGet([$key]);if(!array_key_exists($key,$r['data']??[]))return'API-Key nicht in Antwort enthalten: '.$key;$v=$this->CleanString((string)$r['data'][$key]);$d=$this->DetectValueType($v);$a=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');$a[$key]=$this->MergeApiKeyObservation($key,$v,$d,$a[$key]??[],date('Y-m-d H:i:s'),'');$this->WriteCsvAssoc('api_keys',array_values($a));$this->UpdateBrowserFormList($this->BuildBrowserRows());return'API-Key getestet: '.$key.' | Wert: '.$v.' | erkannt: '.$d.' | effektiv: '.$a[$key]['value_type'];}catch(Throwable $e){return'API-Key Testfehler: '.$e->getMessage();}}

    public function RunScan():string{try{$this->InitializeStorage();$keys=$this->BuildScanKeys();$sid=$this->GetNextScanId();$now=date('Y-m-d H:i:s');$api=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');$dev=$this->IndexBy($this->ReadCsvAssoc('devices'),'code');$dk=$this->ReadCsvAssoc('device_keys');$obs=[];$found=0;$dur=0;foreach(array_chunk($keys,max(1,min(100,$this->ReadPropertyInteger('ScanBatchSize'))))as$c){$r=$this->ApiGet($c);$dur+=(int)($r['_meta']['duration_ms']??0);foreach(($r['data']??[])as$k=>$v){$v=$this->CleanString((string)$v);if($v==='')continue;$d=$this->DetectValueType($v);$api[$k]=$this->MergeApiKeyObservation((string)$k,$v,$d,$api[$k]??[],$now,(string)$sid);$obs[]=['scan_id'=>(string)$sid,'api_key'=>(string)$k,'value'=>$v,'value_type'=>$d,'observed_at'=>$now];$this->ClassifyDevice((string)$k,$now,$dev,$dk);$found++;}}$this->WriteCsvAssoc('api_keys',array_values($api));$this->AppendCsvAssoc('observations',$obs);$this->WriteCsvAssoc('devices',array_values($dev));$this->WriteCsvAssoc('device_keys',$this->UniqueRows($dk,['device_code','api_key']));$fin=date('Y-m-d H:i:s');$this->AppendCsvAssoc('scans',[['scan_id'=>(string)$sid,'started_at'=>$now,'finished_at'=>$fin,'host'=>$this->ReadPropertyString('Host'),'port'=>(string)$this->ReadPropertyInteger('Port'),'generated_keys'=>(string)count($keys),'found_keys'=>(string)$found,'duration_ms'=>(string)$dur,'notes'=>'CSV scan']]);$this->SetValueSafe('LastScanId',$sid);$this->SetValueSafe('LastScanGeneratedKeys',count($keys));$this->SetValueSafe('LastScanFoundKeys',$found);$this->SetValueSafe('LastResponseTimeMs',$dur);$this->SetValueSafe('ScanSummary',$this->BuildScanSummary());$this->UpdateBrowserFormList($this->BuildBrowserRows());$this->UpdateDeviceFormList($this->BuildDeviceRows());return'Scan abgeschlossen. Scan-ID: '.$sid.', erzeugte Keys: '.count($keys).', gefunden: '.$found.', Dauer API: '.$dur.' ms';}catch(Throwable $e){return'Scan-Fehler: '.$e->getMessage();}}
    public function GetScanSummary():string{$m=$this->BuildScanSummary();$this->SetValueSafe('ScanSummary',$m);return$m;}
    public function LoadBrowser():string{$r=$this->BuildBrowserRows();$this->UpdateBrowserFormList($r);return'API-Key Browser geladen. Zeilen: '.count($r);}
    public function LoadDevices():string{$r=$this->BuildDeviceRows();$this->UpdateDeviceFormList($r);return'Device Browser geladen. Devices: '.count($r);}
    public function DiscoverDeviceFamilyFor(string $c,string $s):string{return$this->DiscoverDeviceRangeFor($c,$s,0);}public function DiscoverDeviceNeighborsFor(string $c,string $s,int $r):string{return$this->DiscoverDeviceRangeFor($c,$s,max(1,min(5,$r)));}

    public function LoadApiKeyDetailsFor(string $key):string{$key=trim($key);$a=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');if($key===''||!isset($a[$key]))return'API-Key nicht gefunden: '.$key;$r=$a[$key];$d='API-Key: '.$key."\nDevice: ".$this->GetDeviceForApiKey($key)."\nWert: ".($r['current_value']??'')."\nErkannter Typ: ".($r['detected_value_type']??'')."\nEffektiver Typ: ".($r['value_type']??'')."\nTyp-Override: ".($r['type_override']??'auto')."\nSemantik: ".($r['semantic_type']??'')."\nProfil: ".($r['profile_override']??'')."\nEinheit: ".($r['unit_override']??'')."\nGateway-Import: ".(($r['gateway_import_enabled']??'0')==='1'?'ja':'nein')."\nKommentar: ".($r['comment']??'');$this->SetValueSafe('SelectedApiKeyDetails',$d);return$d;}
    public function SaveApiKeyMetadataFor(string $key,string $t,string $s,string $p,string $u):string{$key=trim($key);$t=strtolower(trim($t));if($t==='')$t='auto';if(!in_array($t,['auto','boolean','integer','float','string','enum'],true))return'Ungueltiger Typ. Erlaubt: auto, boolean, integer, float, string, enum.';$a=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');if(!isset($a[$key]))return'API-Key nicht gefunden: '.$key;$d=(string)($a[$key]['detected_value_type']??$a[$key]['value_type']??'string');$a[$key]['type_override']=$t;$a[$key]['value_type']=$this->ResolveEffectiveType($d,$t);$a[$key]['semantic_type']=trim($s);$a[$key]['profile_override']=trim($p);$a[$key]['unit_override']=trim($u);$this->WriteCsvAssoc('api_keys',array_values($a));$this->UpdateBrowserFormList($this->BuildBrowserRows());return'Typ/Semantik gespeichert: '.$key.' | erkannt: '.$d.' | effektiv: '.$a[$key]['value_type'].'.';}
    public function SaveApiKeyCommentFor(string $key,string $c):string{return$this->UpdateApiKeyField($key,'comment',trim($c),'Kommentar gespeichert: ');}
    public function SaveGatewayVariableNameFor(string $key,string $n):string{return$this->UpdateApiKeyField($key,'gateway_variable_name',trim($n),'Gateway-Variablenname gespeichert: ');}
    public function ToggleGatewayImportFor(string $key):string{$a=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');if(!isset($a[$key]))return'API-Key nicht gefunden: '.$key;$a[$key]['gateway_import_enabled']=($a[$key]['gateway_import_enabled']??'0')==='1'?'0':'1';$this->WriteCsvAssoc('api_keys',array_values($a));$this->UpdateBrowserFormList($this->BuildBrowserRows());$this->UpdateDeviceFormList($this->BuildDeviceRows());return'Gateway-Import '.($a[$key]['gateway_import_enabled']==='1'?'aktiviert':'deaktiviert').': '.$key;}
    public function ToggleFavoriteFor(string $key):string{$a=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');if(!isset($a[$key]))return'API-Key nicht gefunden: '.$key;$a[$key]['is_favorite']=($a[$key]['is_favorite']??'0')==='1'?'0':'1';$this->WriteCsvAssoc('api_keys',array_values($a));$this->UpdateBrowserFormList($this->BuildBrowserRows());return'Favorit umgeschaltet: '.$key;}

    public function AssignApiKeyToDeviceFor(string $key,string $code,string $name,string $type,string $role):string{$key=trim($key);$code=trim($code);if($key===''||$code===''||!preg_match('/^[A-Za-z0-9_\-]+$/',$code))return'Ungueltiger API-Key oder Device-Code.';$a=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');if(!isset($a[$key]))return'API-Key nicht gefunden: '.$key;$name=trim($name)?:$code;$type=trim($type)?:'sensor_group';$role=trim($role)?:'measurement';$now=date('Y-m-d H:i:s');$dev=$this->IndexBy($this->ReadCsvAssoc('devices'),'code');$old=$dev[$code]??[];$dev[$code]=['code'=>$code,'name'=>$name,'device_type'=>$type,'confidence'=>'100','status_key'=>$role==='status'?$key:($old['status_key']??''),'value_key'=>in_array($role,['value','measurement'],true)?$key:($old['value_key']??''),'first_seen'=>$old['first_seen']??$now,'last_seen'=>$now];$dk=array_values(array_filter($this->ReadCsvAssoc('device_keys'),fn($r)=>($r['api_key']??'')!==$key));$dk[]=['device_code'=>$code,'api_key'=>$key,'role'=>$role,'is_required'=>in_array($role,['status','value','measurement'],true)?'1':'0','direction'=>'read','assignment_source'=>'manual'];$this->WriteCsvAssoc('devices',array_values($dev));$this->WriteCsvAssoc('device_keys',$dk);$this->UpdateBrowserFormList($this->BuildBrowserRows());$this->UpdateDeviceFormList($this->BuildDeviceRows());return'Manuelle Device-Zuordnung gespeichert: '.$key.' -> '.$code.' ('.$role.').';}
    public function LoadDeviceDetailsFor(string $code):string{$dev=$this->IndexBy($this->ReadCsvAssoc('devices'),'code');if(!isset($dev[$code]))return'Device nicht gefunden: '.$code;$a=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');$lines=[];foreach($this->ReadCsvAssoc('device_keys')as$k)if(($k['device_code']??'')===$code){$x=$a[$k['api_key']]??[];$lines[]=(($k['is_required']??'0')==='1'?'Pflicht':'Optional').' | '.($k['role']??'').' | '.($k['api_key']??'').' | Zuordnung: '.($k['assignment_source']??'auto').' | Import: '.(($x['gateway_import_enabled']??'0')==='1'?'ja':'nein').' | '.($x['current_value']??'').' | erkannt: '.($x['detected_value_type']??'').' | effektiv: '.($x['value_type']??'');}$d=$dev[$code];$out='Device: '.($d['name']??'')."\nCode: $code\nTyp: ".($d['device_type']??'')."\nVertrauen: ".($d['confidence']??'')."\nStatus-Key: ".($d['status_key']??'')."\nValue-Key: ".($d['value_key']??'')."\n\nKeys:\n".implode("\n",$lines);$this->SetValueSafe('SelectedDeviceDetails',$out);return$out;}
    public function PreviewDeviceExportFor(string $code):string{$dev=$this->IndexBy($this->ReadCsvAssoc('devices'),'code');if(!isset($dev[$code]))return'Device nicht gefunden: '.$code;$a=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');$lines=[];foreach($this->ReadCsvAssoc('device_keys')as$k)if(($k['device_code']??'')===$code){$x=$a[$k['api_key']]??[];if(($x['gateway_import_enabled']??'0')!=='1')continue;$n=trim((string)($x['gateway_variable_name']??''))?:trim((string)($x['suggested_name']??''))?:($k['api_key']??'');$lines[]=($k['api_key']??'').' | Variable: '.$n.' | Typ: '.($x['value_type']??'').' | Semantik: '.($x['semantic_type']??'').' | Wert: '.($x['current_value']??'');}$d=$dev[$code];$out="Gateway Export-Vorschau\nDevice: ".($d['name']??'')."\nCode: $code\nAktivierte Variablen: ".count($lines)."\n\nVariablen:\n".(count($lines)?implode("\n",$lines):'[keine]');$this->SetValueSafe('DeviceExportPreview',$out);return$out;}

    private function DiscoverDeviceRangeFor(string $code,string $status,int $radius):string{$dev=$this->IndexBy($this->ReadCsvAssoc('devices'),'code');if(!isset($dev[$code]))return'Device nicht gefunden: '.$code;if(!preg_match('/^(\d+)\.(\d+)\.status$/',trim($status),$m))return'Ungueltiger Status-Key.';$g=(int)$m[1];$o=(int)$m[2];$s=array_values(array_unique(array_merge(['status','value','opmode','text1','text2'],$this->ParseSuffixes($this->ReadPropertyString('ScanSuffixes')))));$keys=[];for($i=max(1,$o-$radius);$i<=$o+$radius;$i++)foreach($s as$x)$keys[]="$g.$i.$x";try{$r=$this->ApiGet($keys);$data=$r['data']??[];if(!isset($data[$status]))return'Status-Key wurde vom PM5 nicht geliefert: '.$status;$a=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');$dk=$this->ReadCsvAssoc('device_keys');$found=$assigned=$protected=0;$now=date('Y-m-d H:i:s');foreach($data as$k=>$v){$v=$this->CleanString((string)$v);if($v==='')continue;$found++;$md=$this->GetManualAssignmentDevice((string)$k,$dk);if($md!==''&&$md!==$code){$protected++;continue;}$d=$this->DetectValueType($v);$a[$k]=$this->MergeApiKeyObservation((string)$k,$v,$d,$a[$k]??[],$now,'');$dk=array_values(array_filter($dk,fn($x)=>($x['api_key']??'')!==$k));$role=$this->GetRoleForSuffix($this->GetKeySuffix((string)$k));$dk[]=['device_code'=>$code,'api_key'=>(string)$k,'role'=>$role,'is_required'=>in_array($role,['status','value','measurement'],true)?'1':'0','direction'=>'read','assignment_source'=>'manual'];$assigned++;}$dev[$code]['status_key']=$status;$dev[$code]['confidence']='100';$dev[$code]['last_seen']=$now;$vk="$g.$o.value";if(isset($a[$vk]))$dev[$code]['value_key']=$vk;$this->WriteCsvAssoc('api_keys',array_values($a));$this->WriteCsvAssoc('devices',array_values($dev));$this->WriteCsvAssoc('device_keys',$this->UniqueRows($dk,['device_code','api_key']));$this->UpdateBrowserFormList($this->BuildBrowserRows());$this->UpdateDeviceFormList($this->BuildDeviceRows());return($radius===0?'Device-Familie':'Device-Nachbarschaft Radius '.$radius).' abgeschlossen: '.$code.' | Status-Key: '.$status.' | getestet: '.count($keys).' | gefunden: '.$found.' | zugeordnet: '.$assigned.' | geschuetzt: '.$protected.'.';}catch(Throwable $e){return'Device-Familienfehler: '.$e->getMessage();}}

    private function MergeApiKeyObservation(string $k,string $v,string $d,array $e,string $now,string $sid):array{$ov=trim((string)($e['type_override']??''))?:'auto';return['api_key'=>$k,'current_value'=>$v,'detected_value_type'=>$d,'value_type'=>$this->ResolveEffectiveType($d,$ov),'type_override'=>$ov,'semantic_type'=>$e['semantic_type']??'','profile_override'=>$e['profile_override']??'','unit_override'=>$e['unit_override']??'','confidence'=>$e['confidence']??(string)$this->GetConfidence($k),'suggested_name'=>($e['suggested_name']??'')!==''?$e['suggested_name']:$this->GetKnownName($k),'is_favorite'=>$e['is_favorite']??'0','first_seen'=>$e['first_seen']??$now,'last_seen'=>$now,'last_scan_id'=>$sid!==''?$sid:($e['last_scan_id']??''),'comment'=>$e['comment']??'','gateway_variable_name'=>$e['gateway_variable_name']??'','gateway_import_enabled'=>$e['gateway_import_enabled']??'0'];}
    private function ResolveEffectiveType(string $d,string $o):string{if($o===''||$o==='auto')return$d;if($o==='boolean')return'boolean-candidate';if($o==='enum')return'integer';return$o;}
    private function UpdateApiKeyField(string $key,string $f,string $v,string $msg):string{$a=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');if(!isset($a[$key]))return'API-Key nicht gefunden: '.$key;$a[$key][$f]=$v;$this->WriteCsvAssoc('api_keys',array_values($a));$this->UpdateBrowserFormList($this->BuildBrowserRows());return$msg.$key;}

