    private function BuildBrowserRows():array{$dev=$this->GetDeviceByKeyMap();$src=$this->GetAssignmentSourceByKeyMap();$r=[];foreach($this->ReadCsvAssoc('api_keys')as$x){$k=$x['api_key']??'';$r[]=['gateway_import'=>(($x['gateway_import_enabled']??'0')==='1'?'ja':''),'api_key'=>$k,'suggested_name'=>$x['suggested_name']??'','current_value'=>$x['current_value']??'','detected_value_type'=>$x['detected_value_type']??'','value_type'=>$x['value_type']??'','semantic_type'=>$x['semantic_type']??'','device'=>$dev[$k]??'','assignment_source'=>$src[$k]??'','comment'=>$x['comment']??'','last_seen'=>$x['last_seen']??''];}usort($r,fn($a,$b)=>strcmp($b['last_seen'],$a['last_seen']));return array_slice($r,0,250);}
    private function BuildDeviceRows():array{$c=[];$ic=[];$a=$this->IndexBy($this->ReadCsvAssoc('api_keys'),'api_key');foreach($this->ReadCsvAssoc('device_keys')as$d){$x=$d['device_code']??'';$k=$d['api_key']??'';if($x==='')continue;$c[$x]=($c[$x]??0)+1;if(($a[$k]['gateway_import_enabled']??'0')==='1')$ic[$x]=($ic[$x]??0)+1;}$r=[];foreach($this->ReadCsvAssoc('devices')as$d){$x=$d['code']??'';$r[]=['code'=>$x,'name'=>$d['name']??'','device_type'=>$d['device_type']??'','confidence'=>$d['confidence']??'','key_count'=>(string)($c[$x]??0),'import_count'=>(string)($ic[$x]??0),'status_key'=>$d['status_key']??''];}return$r;}
