    private function InitializeStorage():void{$dir=$this->GetStorageDirectory();if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new Exception('CSV-Verzeichnis konnte nicht erstellt werden: '.$dir);foreach(self::CSV_FILES as$n=>$h){$p=$this->GetCsvPath($n);if(!is_file($p))$this->WriteRawCsv($p,[$h]);else$this->EnsureCsvHeader($n);}$this->MigrateApiKeyTypes();$this->WriteCsvAssoc('meta',[['key'=>'schema_version','value'=>(string)self::SCHEMA_VERSION],['key'=>'version','value'=>'0.2.0-alpha']]);}
    private function MigrateApiKeyTypes():void{$r=$this->ReadCsvAssoc('api_keys');$ch=false;foreach($r as&$x){if(($x['detected_value_type']??'')===''){$x['detected_value_type']=$x['value_type']??'string';$ch=true;}if(($x['type_override']??'')===''){$x['type_override']='auto';$ch=true;}$e=$this->ResolveEffectiveType($x['detected_value_type'],$x['type_override']);if(($x['value_type']??'')!==$e){$x['value_type']=$e;$ch=true;}}unset($x);if($ch)$this->WriteCsvAssoc('api_keys',$r);}
    private function EnsureCsvHeader(string $n):void{$p=$this->GetCsvPath($n);$h=fopen($p,'rb');$old=$h?fgetcsv($h,0,';','"',''):[];if($h)fclose($h);if(count(array_diff(self::CSV_FILES[$n],is_array($old)?$old:[]))===0)return;$this->WriteCsvAssoc($n,$this->ReadCsvAssoc($n));}
    private function ReadCsvAssoc(string $n):array{$p=$this->GetCsvPath($n);if(!is_file($p))return[];$h=fopen($p,'rb');if(!$h)throw new Exception('CSV konnte nicht gelesen werden: '.$p);flock($h,LOCK_SH);$head=fgetcsv($h,0,';','"','');$r=[];if(is_array($head))while(($d=fgetcsv($h,0,';','"',''))!==false){$x=[];foreach($head as$i=>$k)$x[$k]=$d[$i]??'';if(implode('',$x)!=='')$r[]=$x;}flock($h,LOCK_UN);fclose($h);return$r;}
    private function WriteCsvAssoc(string $n,array $rows):void{$head=self::CSV_FILES[$n];$d=[$head];foreach($rows as$r)$d[]=array_map(fn($k)=>(string)($r[$k]??''),$head);$this->WriteRawCsv($this->GetCsvPath($n),$d);}private function AppendCsvAssoc(string $n,array $rows):void{if(!$rows)return;$h=fopen($this->GetCsvPath($n),'ab');flock($h,LOCK_EX);foreach($rows as$r){$l=[];foreach(self::CSV_FILES[$n]as$k)$l[]=(string)($r[$k]??'');fputcsv($h,$l,';','"','');}flock($h,LOCK_UN);fclose($h);}private function WriteRawCsv(string $p,array $rows):void{$t=$p.'.tmp';$h=fopen($t,'wb');foreach($rows as$r)fputcsv($h,$r,';','"','');fclose($h);if(!rename($t,$p))throw new Exception('CSV konnte nicht ersetzt werden: '.$p);}
    private function GetNextScanId():int{$m=0;foreach($this->ReadCsvAssoc('scans')as$s)$m=max($m,(int)($s['scan_id']??0));return$m+1;}

    private function ClassifyDevice(string $k,string $now,array &$dev,array &$dk):void{if($this->HasManualAssignment($k,$dk))return;if(strpos($k,'55.17106.')===0)$this->EnsureDevice('filter_pump','Filterpumpe','actuator',$k,$this->GetKeySuffix($k),$now,$dev,$dk);if(strpos($k,'55.17102.')===0)$this->EnsureDevice('pool_light','Poollicht','actuator',$k,$this->GetKeySuffix($k),$now,$dev,$dk);if(strpos($k,'34.')===0)$this->EnsureDevice('water_values','Wasserwerte','sensor_group',$k,'measurement',$now,$dev,$dk);if(strpos($k,'13.')===0)$this->EnsureDevice('system_values','Systemwerte','system_group',$k,'info',$now,$dev,$dk);}
    private function HasManualAssignment(string $k,array $dk):bool{foreach($dk as$r)if(($r['api_key']??'')===$k&&($r['assignment_source']??'auto')==='manual')return true;return false;}private function EnsureDevice(string $c,string $n,string $t,string $k,string $role,string $now,array &$dev,array &$dk):void{$e=$dev[$c]??[];$dev[$c]=['code'=>$c,'name'=>$n,'device_type'=>$t,'confidence'=>'80','status_key'=>$role==='status'?$k:($e['status_key']??''),'value_key'=>in_array($role,['value','measurement'],true)?$k:($e['value_key']??''),'first_seen'=>$e['first_seen']??$now,'last_seen'=>$now];$dk[]=['device_code'=>$c,'api_key'=>$k,'role'=>$role,'is_required'=>in_array($role,['status','value','measurement'],true)?'1':'0','direction'=>'read','assignment_source'=>'auto'];}
    private function ApiGet(array $keys):array{$host=trim($this->ReadPropertyString('Host'));if($host==='')throw new Exception('Host ist leer.');$url='http://'.$host.':'.max(1,min(65535,$this->ReadPropertyInteger('Port'))).'/cgi-bin/webgui.fcgi?sid='.rawurlencode($this->CreateSid());$p=json_encode(['get'=>array_values($keys)]);$ctx=stream_context_create(['http'=>['method'=>'POST','header'=>"Content-Type: application/json;charset=UTF-8\r\nAccept: application/json\r\n",'content'=>$p,'timeout'=>max(1,$this->ReadPropertyInteger('Timeout')),'ignore_errors'=>true]]);$st=microtime(true);$raw=@file_get_contents($url,false,$ctx);if($raw===false)throw new Exception('HTTP request failed.');$j=json_decode($raw,true);if(!is_array($j)||(int)($j['status']['code']??-1)!==0)throw new Exception('API Fehler.');$j['_meta']=['duration_ms'=>(int)round((microtime(true)-$st)*1000)];return$j;}
    private function BuildScanKeys():array{$r=[];$s=$this->ParseSuffixes($this->ReadPropertyString('ScanSuffixes'));$max=max(1,min(5000,$this->ReadPropertyInteger('ScanMaxKeys')));$firstGroup=max(1,min(999,$this->ReadPropertyInteger('ScanGroupStart')));$lastGroup=max($firstGroup,min(999,$this->ReadPropertyInteger('ScanGroupEnd')));foreach(self::DOCUMENTED_OBJECT_IDS as$g=>$objectIds){if($g<$firstGroup||$g>$lastGroup)continue;foreach($objectIds as$o)foreach($s as$x){$r[]="$g.$o.$x";if(count($r)>=$max)return$r;}}$firstObject=max(1,min(99999,$this->ReadPropertyInteger('ScanObjectStart')));$lastObject=max($firstObject,min(99999,$this->ReadPropertyInteger('ScanObjectEnd')));for($g=$firstGroup;$g<=$lastGroup;$g++){if(isset(self::DOCUMENTED_OBJECT_IDS[$g]))continue;for($o=$firstObject;$o<=$lastObject;$o++)foreach($s as$x){$r[]="$g.$o.$x";if(count($r)>=$max)return$r;}}return$r;}
    private function GetDeviceByKeyMap():array{$m=[];$src=[];foreach($this->ReadCsvAssoc('device_keys')as$d){$k=$d['api_key']??'';$s=$d['assignment_source']??'auto';if($k!==''&&(!isset($m[$k])||$s==='manual'||($src[$k]??'')!=='manual')){$m[$k]=$d['device_code']??'';$src[$k]=$s;}}return$m;}private function GetAssignmentSourceByKeyMap():array{$m=[];foreach($this->ReadCsvAssoc('device_keys')as$d){$k=$d['api_key']??'';$s=$d['assignment_source']??'auto';if($k!==''&&(!isset($m[$k])||$s==='manual'))$m[$k]=$s;}return$m;}private function GetManualAssignmentDevice(string $k,array $dk):string{foreach($dk as$r)if(($r['api_key']??'')===$k&&($r['assignment_source']??'auto')==='manual')return(string)($r['device_code']??'');return'';}private function GetRoleForSuffix(string $s):string{return$s==='status'?'status':($s==='value'?'value':($s==='opmode'?'opmode':'info'));}private function GetDeviceForApiKey(string $k):string{$m=$this->GetDeviceByKeyMap();return$m[$k]??'';}
    private function ParseSuffixes(string $r):array{$r=str_replace(["\r\n","\r",',',';'],"\n",$r);$o=[];foreach(explode("\n",$r)as$x){$x=trim($x);if($x!==''&&preg_match('/^[A-Za-z0-9_]+$/',$x))$o[$x]=$x;}return array_values($o?:['value']);}private function DetectValueType(string $v):string{$n=str_replace(',','.',$v);if($v==='0'||$v==='1')return'boolean-candidate';return is_numeric($n)?(strpos($n,'.')===false?'integer':'float'):'string';}private function GetConfidence(string $k):int{return in_array($k,['34.4001.value','34.4022.value','34.4033.value','13.16507.text2','13.16509.text1','55.17102.status','55.17102.value','55.17106.status','55.17106.opmode','55.17106.value'],true)?100:60;}private function GetKnownName(string $k):string{$n=['34.4001.value'=>'pH','34.4022.value'=>'Redox','34.4033.value'=>'Pooltemperatur','13.16507.text2'=>'Aussentemperatur T3','13.16509.text1'=>'Leitfaehigkeit','55.17106.status'=>'Filterpumpe Status','55.17106.opmode'=>'Filterpumpe Betriebsart','55.17106.value'=>'Filterpumpe Text','55.17102.status'=>'Poollicht Status','55.17102.value'=>'Poollicht Text'];return$n[$k]??'';}private function GetKeySuffix(string $k):string{$p=explode('.',$k);return(string)(end($p)?:'');}private function CleanString(string $v):string{return trim(html_entity_decode(strip_tags($v),ENT_QUOTES|ENT_HTML5,'UTF-8'));}private function CreateSid():string{return'SYMBAYROL'.substr(strtoupper(md5((string)microtime(true).mt_rand())),0,23);}private function IndexBy(array $r,string $k):array{$o=[];foreach($r as$x)if(($x[$k]??'')!=='')$o[$x[$k]]=$x;return$o;}private function UniqueRows(array $r,array $keys):array{$s=[];$o=[];foreach($r as$x){$p=[];foreach($keys as$k)$p[]=$x[$k]??'';$h=implode('|',$p);if(!isset($s[$h])){$s[$h]=1;$o[]=$x;}}return$o;}private function GetStorageDirectory():string{return rtrim(IPS_GetKernelDir(),DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR.'user'.DIRECTORY_SEPARATOR.'BayrolDiscovery';}private function GetCsvPath(string $n):string{return$this->GetStorageD